-- ============================================================
-- Phase 15: VALENCE ADVERTISE & Verified Partner Directory
-- Strictly for (1) Physical Tuition Centres, (2) Accounting
-- Textbook Authors, (3) Verified Textbook Vendors at ₦10,000/week
-- in-app with Paystack billing. 9 Sponsored-labelled placements,
-- anti-piracy/venue verification queue & live CTR analytics.
-- Online tuition is delivered solely in-app by VALENCE-verified tutors.
-- ============================================================

-- ---------- Schema extensions ----------

ALTER TABLE public.advertisers
  ADD COLUMN IF NOT EXISTS category text NOT NULL DEFAULT 'physical_centre',
  ADD COLUMN IF NOT EXISTS isbn_or_publisher text,
  ADD COLUMN IF NOT EXISTS enquiry_count integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS total_impressions integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS total_clicks integer NOT NULL DEFAULT 0;

ALTER TABLE public.advertising_campaigns
  ADD COLUMN IF NOT EXISTS weeks integer NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS placement_count integer NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS total_amount_ngn integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS category text,
  ADD COLUMN IF NOT EXISTS total_impressions integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS total_clicks integer NOT NULL DEFAULT 0;

ALTER TABLE public.advertising_payments
  ADD COLUMN IF NOT EXISTS paystack_verify_job bigint,
  ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();

ALTER TABLE public.advertising_impressions
  ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();

ALTER TABLE public.advertising_clicks
  ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();

ALTER TABLE public.advertising_impressions
  ADD CONSTRAINT uq_impressions_campaign_date UNIQUE (campaign_id, date);
ALTER TABLE public.advertising_clicks
  ADD CONSTRAINT uq_clicks_campaign_date UNIQUE (campaign_id, date);

CREATE TABLE IF NOT EXISTS public.advertising_enquiries (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  campaign_id uuid NOT NULL REFERENCES public.advertising_campaigns(id) ON DELETE CASCADE,
  advertiser_id uuid NOT NULL REFERENCES public.advertisers(id) ON DELETE CASCADE,
  student_profile_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,
  message text NOT NULL DEFAULT '',
  contact_mode text NOT NULL DEFAULT 'enquiry',
  status text NOT NULL DEFAULT 'new',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- ---------- updated_at triggers ----------

CREATE OR REPLACE FUNCTION public.trg_set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $function$;

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['advertisers','advertising_campaigns','advertising_payments','advertising_enquiries','advertising_impressions','advertising_clicks']
  LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS set_updated_at ON public.%I', t);
    EXECUTE format('CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.trg_set_updated_at()', t);
  END LOOP;
END $$;

-- ---------- RLS policies ----------

-- Directory: verified advertisers visible to the public (filtered in RPC too)
DROP POLICY IF EXISTS advertisers_select_verified_public ON public.advertisers;
CREATE POLICY advertisers_select_verified_public ON public.advertisers
  FOR SELECT TO public USING (verification_status = 'verified');

-- Advertising packages readable by public (keep idempotent)
DROP POLICY IF EXISTS advertising_packages_select_public ON public.advertising_packages;
CREATE POLICY advertising_packages_select_public ON public.advertising_packages
  FOR SELECT TO public USING (true);

-- Enquiries: advertiser can read own, student can read own
DROP POLICY IF EXISTS advertising_enquiries_select_own ON public.advertising_enquiries;
CREATE POLICY advertising_enquiries_select_own ON public.advertising_enquiries
  FOR SELECT TO public USING (student_profile_id = auth.uid() OR advertiser_id IN (SELECT id FROM public.advertisers WHERE profile_id = (SELECT id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1)));

-- ---------- Default advertising package (₦10,000/week) ----------

INSERT INTO public.advertising_packages (name, price_ngn, duration_days, placements, banner_sizes, target_audiences, campaign_limits, promotional_offers)
SELECT 'VALENCE Standard Week — ₦10,000/week', 10000, 7,
  ARRAY['home-banner','store-spotlight','ican-sponsored','atswa-sponsored','student-dash','connect-post','featured-dir','learn-slot','book-launch'],
  ARRAY['leaderboard','sidebar','spotlight','card'],
  ARRAY['ATSWA & ICAN Candidates','Accounting Students','Finance Professionals'],
  1, '1 placement slot included per week; up to 9 sponsored slots available.'
WHERE NOT EXISTS (SELECT 1 FROM public.advertising_packages WHERE name = 'VALENCE Standard Week — ₦10,000/week');

-- ============================================================
-- RPCs (all SECURITY DEFINER, error-JSON returns)
-- ============================================================

-- 1. manage_advertiser: create/update own advertiser
CREATE OR REPLACE FUNCTION public.manage_advertiser(p_advertiser_id uuid DEFAULT NULL::uuid, p_centre_name text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_address text DEFAULT ''::text, p_contact_details text DEFAULT ''::text, p_website text DEFAULT ''::text, p_social_links text[] DEFAULT NULL, p_business_description text DEFAULT ''::text, p_areas_of_specialisation text[] DEFAULT NULL, p_programmes_offered text[] DEFAULT NULL, p_credentials text DEFAULT ''::text, p_isbn_or_publisher text DEFAULT ''::text, p_logo_url text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_profile_id uuid; v_advertiser_id uuid; BEGIN SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1; IF v_profile_id IS NULL THEN RETURN jsonb_build_object('error', 'Profile not found for this account.'); END IF; IF p_centre_name IS NULL OR trim(p_centre_name) = '' THEN RETURN jsonb_build_object('error', 'An entity/centre name is required.'); END IF; IF p_category NOT IN ('physical_centre', 'textbook_author', 'textbook_vendor') THEN RETURN jsonb_build_object('error', 'Invalid advertiser category.'); END IF; IF p_category IN ('textbook_author','textbook_vendor') AND (p_isbn_or_publisher IS NULL OR trim(p_isbn_or_publisher) = '') THEN RETURN jsonb_build_object('error', 'ISBN or publisher details are required for textbook categories.'); END IF; IF p_advertiser_id IS NOT NULL THEN SELECT id INTO v_advertiser_id FROM public.advertisers WHERE id = p_advertiser_id AND profile_id = v_profile_id; IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Advertiser not found.'); END IF; ELSE v_advertiser_id := gen_random_uuid(); END IF; INSERT INTO public.advertisers (id, profile_id, centre_name, category, logo_url, address, contact_details, website, social_links, business_description, areas_of_specialisation, programmes_offered, credentials, isbn_or_publisher, verification_status, created_at, updated_at) VALUES (v_advertiser_id, v_profile_id, p_centre_name, p_category, p_logo_url, p_address, p_contact_details, p_website, p_social_links, p_business_description, p_areas_of_specialisation, p_programmes_offered, p_credentials, p_isbn_or_publisher, 'pending', now(), now()) ON CONFLICT (id) DO UPDATE SET centre_name = EXCLUDED.centre_name, category = EXCLUDED.category, logo_url = EXCLUDED.logo_url, address = EXCLUDED.address, contact_details = EXCLUDED.contact_details, website = EXCLUDED.website, social_links = EXCLUDED.social_links, business_description = EXCLUDED.business_description, areas_of_specialisation = EXCLUDED.areas_of_specialisation, programmes_offered = EXCLUDED.programmes_offered, credentials = EXCLUDED.credentials, isbn_or_publisher = EXCLUDED.isbn_or_publisher, updated_at = now(); RETURN jsonb_build_object('status','ok','advertiser_id',v_advertiser_id,'message','Advertiser saved'); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 2. fetch_my_advertiser: own advertiser + verification + campaign summary
CREATE OR REPLACE FUNCTION public.fetch_my_advertiser() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_profile_id uuid; v_adv record; v_latest_ver record; BEGIN SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1; IF v_profile_id IS NULL THEN RETURN jsonb_build_object('error', 'Profile not found for this account.'); END IF; SELECT a.* INTO v_adv FROM public.advertisers a WHERE a.profile_id = v_profile_id LIMIT 1; IF NOT FOUND THEN RETURN jsonb_build_object('advertiser', NULL, 'verification', NULL, 'campaign_count', 0, 'enquiry_count', 0); END IF; SELECT status, notes, verified_at, created_at INTO v_latest_ver FROM public.advertiser_verifications v WHERE v.advertiser_id = v_adv.id ORDER BY v.created_at DESC LIMIT 1; RETURN jsonb_build_object('advertiser', jsonb_build_object('id', v_adv.id, 'centre_name', v_adv.centre_name, 'category', v_adv.category, 'logo_url', v_adv.logo_url, 'address', v_adv.address, 'contact_details', v_adv.contact_details, 'website', v_adv.website, 'social_links', v_adv.social_links, 'business_description', v_adv.business_description, 'areas_of_specialisation', v_adv.areas_of_specialisation, 'programmes_offered', v_adv.programmes_offered, 'credentials', v_adv.credentials, 'isbn_or_publisher', v_adv.isbn_or_publisher, 'verification_status', v_adv.verification_status, 'total_impressions', v_adv.total_impressions, 'total_clicks', v_adv.total_clicks, 'enquiry_count', v_adv.enquiry_count, 'created_at', v_adv.created_at, 'updated_at', v_adv.updated_at), 'verification', CASE WHEN v_latest_ver.status IS NULL THEN NULL ELSE jsonb_build_object('status', v_latest_ver.status, 'notes', v_latest_ver.notes, 'verified_at', v_latest_ver.verified_at, 'created_at', v_latest_ver.created_at) END, 'campaign_count', (SELECT count(*) FROM public.advertising_campaigns c WHERE c.advertiser_id = v_adv.id), 'enquiry_count', v_adv.enquiry_count); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 3. fetch_advertiser_directory: verified advertisers (the Verified Partner Directory)
CREATE OR REPLACE FUNCTION public.fetch_advertiser_directory(p_category text DEFAULT NULL, p_limit int DEFAULT 50, p_offset int DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_rows jsonb; BEGIN SELECT jsonb_agg(jsonb_build_object('id', a.id, 'centre_name', a.centre_name, 'category', a.category, 'address', a.address, 'website', a.website, 'credentials', a.credentials, 'isbn_or_publisher', a.isbn_or_publisher, 'areas_of_specialisation', a.areas_of_specialisation, 'programmes_offered', a.programmes_offered, 'business_description', a.business_description, 'verification_status', a.verification_status, 'total_impressions', a.total_impressions, 'total_clicks', a.total_clicks, 'enquiry_count', a.enquiry_count, 'display_name', p.display_name, 'profile_photo_url', p.profile_photo_url) ORDER BY a.total_impressions DESC, a.created_at DESC) INTO v_rows FROM (SELECT a.*, pr.display_name, pr.profile_photo_url FROM public.advertisers a JOIN public.profiles pr ON pr.id = a.profile_id WHERE a.verification_status = 'verified' AND (p_category IS NULL OR a.category = p_category) ORDER BY a.total_impressions DESC, a.created_at DESC LIMIT p_limit OFFSET p_offset) a JOIN public.profiles p ON p.id = a.profile_id; RETURN v_rows; EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 4. submit_advertiser_verification: request venue/anti-piracy verification
CREATE OR REPLACE FUNCTION public.submit_advertiser_verification(p_verification_type text, p_details text DEFAULT ''::text, p_document_url text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_profile_id uuid; v_advertiser_id uuid; v_verification_id uuid; BEGIN SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1; IF v_profile_id IS NULL THEN RETURN jsonb_build_object('error', 'Profile not found for this account.'); END IF; SELECT id INTO v_advertiser_id FROM public.advertisers WHERE profile_id = v_profile_id LIMIT 1; IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Set up your advertiser profile first.'); END IF; IF p_verification_type IS NULL OR trim(p_verification_type) = '' THEN RETURN jsonb_build_object('error', 'Verification type is required.'); END IF; INSERT INTO public.advertiser_verifications (advertiser_id, status, notes, created_at, updated_at) VALUES (v_advertiser_id, 'pending', p_details, now(), now()) RETURNING id INTO v_verification_id; UPDATE public.advertisers SET verification_status = 'pending', updated_at = now() WHERE id = v_advertiser_id; RETURN jsonb_build_object('status','ok','verification_id',v_verification_id,'message','Verification request submitted'); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 5. fetch_advertiser_verification_queue: admin
CREATE OR REPLACE FUNCTION public.fetch_advertiser_verification_queue(p_status text DEFAULT 'pending') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; RETURN (SELECT jsonb_agg(jsonb_build_object('id', v.id, 'advertiser_id', v.advertiser_id, 'centre_name', a.centre_name, 'category', a.category, 'status', v.status, 'notes', v.notes, 'verified_at', v.verified_at, 'verified_by', v.verified_by, 'created_at', v.created_at, 'isbn_or_publisher', a.isbn_or_publisher, 'address', a.address) ORDER BY v.created_at DESC) FROM public.advertiser_verifications v JOIN public.advertisers a ON a.id = v.advertiser_id WHERE v.status = p_status); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 6. review_advertiser_verification: admin approve/reject
CREATE OR REPLACE FUNCTION public.review_advertiser_verification(p_verification_id uuid, p_approved boolean, p_notes text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_advertiser_id uuid; v_profile_id uuid; v_status text; BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; SELECT advertiser_id INTO v_advertiser_id FROM public.advertiser_verifications WHERE id = p_verification_id; IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Verification request not found.'); END IF; v_status := CASE WHEN p_approved THEN 'approved' ELSE 'rejected' END; UPDATE public.advertiser_verifications SET status = v_status, notes = COALESCE(p_notes, notes), verified_by = auth.uid(), verified_at = now(), updated_at = now() WHERE id = p_verification_id; UPDATE public.advertisers SET verification_status = CASE WHEN p_approved THEN 'verified' ELSE 'rejected' END, updated_at = now() WHERE id = v_advertiser_id; SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1; INSERT INTO public.advertising_audit_logs (campaign_id, actor_profile_id, action, details, created_at) VALUES (NULL, v_profile_id, 'review_advertiser_verification', jsonb_build_object('verification_id', p_verification_id, 'advertiser_id', v_advertiser_id, 'decision', v_status), now()); RETURN jsonb_build_object('status','ok','verification_id',p_verification_id,'decision',v_status); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 7. fetch_advertising_packages: public list
CREATE OR REPLACE FUNCTION public.fetch_advertising_packages() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ BEGIN RETURN (SELECT jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'price_ngn', p.price_ngn, 'duration_days', p.duration_days, 'placements', p.placements, 'banner_sizes', p.banner_sizes, 'target_audiences', p.target_audiences, 'campaign_limits', p.campaign_limits, 'promotional_offers', p.promotional_offers) ORDER BY p.price_ngn ASC) FROM public.advertising_packages p); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 8. fetch_advertising_placements: the 9 Sponsored placement slots
CREATE OR REPLACE FUNCTION public.fetch_advertising_placements() RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ SELECT jsonb_build_array( jsonb_build_object('id','home-banner','label','Homepage Promotional Banner','location','Home page top banner'), jsonb_build_object('id','store-spotlight','label','Study Materials & Bookstore Spotlight','location','Store spotlight'), jsonb_build_object('id','ican-sponsored','label','Sponsored ICAN Programme Placement','location','ICAN programme pages'), jsonb_build_object('id','atswa-sponsored','label','Sponsored ATSWA Programme Placement','location','ATSWA programme pages'), jsonb_build_object('id','student-dash','label','Student Dashboard Placement','location','Student dashboard'), jsonb_build_object('id','connect-post','label','Sponsored VALENCE CONNECT Post','location','Community feed'), jsonb_build_object('id','featured-dir','label','Featured Directory Card','location','Verified Partner Directory'), jsonb_build_object('id','learn-slot','label','Learning & Syllabus Section Placement','location','Learning / syllabus pages'), jsonb_build_object('id','book-launch','label','New Textbook Launch / Physical Workshop Card','location','Textbook & workshop cards') ); $function$;

-- 9. manage_advertising_campaign: create/update campaign (pending payment)
CREATE OR REPLACE FUNCTION public.manage_advertising_campaign(p_campaign_id uuid DEFAULT NULL::uuid, p_advertiser_id uuid DEFAULT NULL::uuid, p_package_id uuid DEFAULT NULL::uuid, p_campaign_name text DEFAULT NULL::text, p_banner_url text DEFAULT NULL, p_copy_text text DEFAULT ''::text, p_contact_link text DEFAULT NULL, p_target_audiences text[] DEFAULT NULL, p_placements text[] DEFAULT NULL, p_weeks int DEFAULT 1, p_start_date timestamptz DEFAULT NULL, p_end_date timestamptz DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_profile_id uuid; v_advertiser record; v_pkg record; v_campaign_id uuid; v_total int; v_placement text; v_count int; BEGIN SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1; IF v_profile_id IS NULL THEN RETURN jsonb_build_object('error', 'Profile not found for this account.'); END IF; SELECT * INTO v_advertiser FROM public.advertisers WHERE id = p_advertiser_id; IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Advertiser not found.'); END IF; IF v_advertiser.profile_id IS DISTINCT FROM v_profile_id THEN RETURN jsonb_build_object('error', 'This advertiser does not belong to your account.'); END IF; IF v_advertiser.verification_status <> 'verified' THEN RETURN jsonb_build_object('error', 'Your advertiser profile must be verified before booking a campaign.'); END IF; IF p_campaign_name IS NULL OR trim(p_campaign_name) = '' THEN RETURN jsonb_build_object('error', 'A campaign name is required.'); END IF; SELECT * INTO v_pkg FROM public.advertising_packages WHERE id = p_package_id; IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Selected advertising package not found.'); END IF; v_count := COALESCE(array_length(p_placements, 1), 1); IF v_count < 1 THEN v_count := 1; END IF; IF v_count > 9 THEN v_count := 9; END IF; v_total := GREATEST(p_weeks,1) * v_count * COALESCE(v_pkg.price_ngn, 10000); IF p_campaign_id IS NOT NULL THEN SELECT id INTO v_campaign_id FROM public.advertising_campaigns WHERE id = p_campaign_id AND advertiser_id = p_advertiser_id; IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Campaign not found.'); END IF; DELETE FROM public.advertising_placements WHERE campaign_id = v_campaign_id; ELSE v_campaign_id := gen_random_uuid(); END IF; INSERT INTO public.advertising_campaigns (id, advertiser_id, package_id, campaign_name, banner_url, promotional_images, copy_text, contact_link, target_audiences, placements, weeks, placement_count, total_amount_ngn, category, start_date, end_date, status, payment_verified_at, created_at, updated_at) VALUES (v_campaign_id, p_advertiser_id, p_package_id, p_campaign_name, p_banner_url, NULL, p_copy_text, p_contact_link, p_target_audiences, p_placements, GREATEST(p_weeks,1), v_count, v_total, v_advertiser.category, p_start_date, p_end_date, 'pending_payment', NULL, now(), now()) ON CONFLICT (id) DO UPDATE SET package_id = EXCLUDED.package_id, campaign_name = EXCLUDED.campaign_name, banner_url = EXCLUDED.banner_url, copy_text = EXCLUDED.copy_text, contact_link = EXCLUDED.contact_link, target_audiences = EXCLUDED.target_audiences, placements = EXCLUDED.placements, weeks = EXCLUDED.weeks, placement_count = EXCLUDED.placement_count, total_amount_ngn = EXCLUDED.total_amount_ngn, start_date = EXCLUDED.start_date, end_date = EXCLUDED.end_date, status = 'pending_payment', payment_verified_at = NULL, updated_at = now(); FOR v_placement IN SELECT unnest(COALESCE(p_placements, ARRAY['featured-dir']::text[])) LOOP INSERT INTO public.advertising_placements (campaign_id, placement_name, placement_location, created_at) VALUES (v_campaign_id, v_placement, NULL, now()); END LOOP; RETURN jsonb_build_object('status','ok','campaign_id',v_campaign_id,'total_amount_ngn',v_total,'weeks',GREATEST(p_weeks,1),'placement_count',v_count,'message','Campaign created - complete payment to activate'); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 10. fetch_my_advertising_campaigns: own campaigns with placements + payment
CREATE OR REPLACE FUNCTION public.fetch_my_advertising_campaigns() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_profile_id uuid; v_rows jsonb; BEGIN SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1; IF v_profile_id IS NULL THEN RETURN jsonb_build_object('error', 'Profile not found for this account.'); END IF; SELECT jsonb_agg(jsonb_build_object('id', c.id, 'campaign_name', c.campaign_name, 'category', c.category, 'banner_url', c.banner_url, 'copy_text', c.copy_text, 'contact_link', c.contact_link, 'placements', c.placements, 'weeks', c.weeks, 'placement_count', c.placement_count, 'total_amount_ngn', c.total_amount_ngn, 'status', c.status, 'paystack_reference', c.paystack_reference, 'payment_verified_at', c.payment_verified_at, 'start_date', c.start_date, 'end_date', c.end_date, 'created_at', c.created_at, 'payments', coalesce((SELECT jsonb_agg(jsonb_build_object('id', p.id, 'amount_ngn', p.amount_ngn, 'paystack_reference', p.paystack_reference, 'status', p.status, 'verified_at', p.verified_at) ORDER BY p.created_at DESC) FROM public.advertising_payments p WHERE p.campaign_id = c.id), '[]'::jsonb)) ORDER BY c.created_at DESC) INTO v_rows FROM public.advertising_campaigns c WHERE c.advertiser_id IN (SELECT id FROM public.advertisers WHERE profile_id = v_profile_id); RETURN v_rows; EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 11. fetch_advertising_campaigns: admin list
CREATE OR REPLACE FUNCTION public.fetch_advertising_campaigns(p_status text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; RETURN (SELECT jsonb_agg(jsonb_build_object('id', c.id, 'campaign_name', c.campaign_name, 'advertiser_id', c.advertiser_id, 'centre_name', a.centre_name, 'category', c.category, 'weeks', c.weeks, 'placement_count', c.placement_count, 'total_amount_ngn', c.total_amount_ngn, 'status', c.status, 'paystack_reference', c.paystack_reference, 'payment_verified_at', c.payment_verified_at, 'start_date', c.start_date, 'end_date', c.end_date, 'created_at', c.created_at) ORDER BY c.created_at DESC) FROM public.advertising_campaigns c JOIN public.advertisers a ON a.id = c.advertiser_id WHERE (p_status IS NULL OR c.status = p_status)); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 12. create_advertising_payment: server-authoritative amount + pending payment row
CREATE OR REPLACE FUNCTION public.create_advertising_payment(p_campaign_id uuid DEFAULT NULL::uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_profile_id uuid; v_campaign record; v_pkg record; v_payment_id uuid; v_reference text; v_amount int; BEGIN SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1; IF v_profile_id IS NULL THEN RETURN jsonb_build_object('error', 'Profile not found for this account.'); END IF; SELECT * INTO v_campaign FROM public.advertising_campaigns WHERE id = p_campaign_id; IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Campaign not found.'); END IF; IF v_campaign.advertiser_id IS DISTINCT FROM (SELECT id FROM public.advertisers WHERE profile_id = v_profile_id LIMIT 1) THEN RETURN jsonb_build_object('error', 'This campaign does not belong to your account.'); END IF; IF v_campaign.status <> 'pending_payment' THEN RETURN jsonb_build_object('error', 'This campaign is not awaiting payment.'); END IF; SELECT price_ngn INTO v_pkg FROM public.advertising_packages WHERE id = v_campaign.package_id; v_amount := GREATEST(v_campaign.weeks,1) * GREATEST(v_campaign.placement_count,1) * COALESCE(v_pkg.price_ngn, 10000); SELECT upper(substring(md5(random()::text || clock_timestamp()::text) from 1 for 12)) INTO v_reference; INSERT INTO public.advertising_payments (campaign_id, amount_ngn, paystack_reference, status, created_at) VALUES (p_campaign_id, v_amount, v_reference, 'pending', now()) RETURNING id INTO v_payment_id; UPDATE public.advertising_campaigns SET total_amount_ngn = v_amount, updated_at = now() WHERE id = p_campaign_id; RETURN jsonb_build_object('status','ok','payment_id',v_payment_id,'campaign_id',p_campaign_id,'amount_ngn',v_amount,'currency','NGN','reference',v_reference); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 13. verify_advertising_payment: Paystack verification (reuses store pattern)
CREATE OR REPLACE FUNCTION public.verify_advertising_payment(p_payment_id uuid, p_reference text, p_amount int) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_payment record; v_campaign record; v_secret text; v_job bigint; v_status int; v_content text; v_timed_out boolean; v_err text; v_body jsonb; v_data jsonb; v_now timestamptz := now(); v_profile_id uuid; BEGIN SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1; IF v_profile_id IS NULL THEN RETURN jsonb_build_object('error', 'Profile not found for this account.'); END IF; SELECT * INTO v_payment FROM public.advertising_payments WHERE id = p_payment_id; IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Payment not found.'); END IF; IF v_payment.campaign_id IS DISTINCT FROM (SELECT id FROM public.advertising_campaigns c JOIN public.advertisers a ON a.id = c.advertiser_id WHERE a.profile_id = v_profile_id AND c.id = v_payment.campaign_id LIMIT 1) THEN RETURN jsonb_build_object('error', 'This payment does not belong to your account.'); END IF; IF v_payment.status = 'succeeded' AND v_payment.paystack_reference = p_reference THEN RETURN jsonb_build_object('status','ok','payment_id',v_payment.id,'campaign_id',v_payment.campaign_id,'amount_ngn',v_payment.amount_ngn,'paystack_reference',p_reference,'server_verified',true,'message','Already verified'); END IF; IF v_payment.status = 'succeeded' THEN RETURN jsonb_build_object('error', 'This payment is already verified.'); END IF; IF p_amount IS DISTINCT FROM v_payment.amount_ngn THEN RETURN jsonb_build_object('error', 'The reported payment amount does not match the campaign total.'); END IF; SELECT * INTO v_campaign FROM public.advertising_campaigns WHERE id = v_payment.campaign_id; IF v_campaign.paystack_verify_job IS NOT NULL OR v_payment.paystack_verify_job IS NOT NULL THEN SELECT status_code, content, timed_out, error_msg INTO v_status, v_content, v_timed_out, v_err FROM net._http_response WHERE id = COALESCE(v_payment.paystack_verify_job, v_campaign.paystack_verify_job); IF NOT FOUND THEN RETURN jsonb_build_object('status','verifying','payment_id',v_payment.id,'message','Paystack verification in progress. Retrying...'); END IF; IF v_timed_out OR v_err IS NOT NULL THEN DELETE FROM net._http_response WHERE id = COALESCE(v_payment.paystack_verify_job, v_campaign.paystack_verify_job); ELSE IF v_status IS NULL OR v_status <> 200 THEN v_body := coalesce(v_content::jsonb, '{}'::jsonb); RETURN jsonb_build_object('error', 'Paystack verification failed: ' || coalesce(v_body->>'message', 'HTTP ' || coalesce(v_status::text,'unknown error'))); END IF; v_body := coalesce(v_content::jsonb, '{}'::jsonb); v_data := coalesce(v_body->'data', '{}'::jsonb); IF v_body->>'status' IS DISTINCT FROM 'true' THEN RETURN jsonb_build_object('error', 'Paystack verification failed: ' || coalesce(v_body->>'message','transaction not successful')); END IF; IF v_data->>'status' NOT IN ('success','completed') THEN RETURN jsonb_build_object('error', 'Paystack transaction not successful: ' || coalesce(v_data->>'status','unknown')); END IF; IF upper(v_data->>'reference') IS DISTINCT FROM upper(p_reference) THEN RETURN jsonb_build_object('error', 'Paystack reference mismatch.'); END IF; IF coalesce((v_data->>'amount')::int, -1) <> p_amount * 100 THEN RETURN jsonb_build_object('error', 'Paystack amount mismatch.'); END IF; UPDATE public.advertising_payments SET status = 'succeeded', verified_at = v_now, paystack_verify_job = NULL, updated_at = now() WHERE id = v_payment.id; UPDATE public.advertising_campaigns SET status = 'active', paystack_reference = p_reference, payment_verified_at = v_now, start_date = COALESCE(v_campaign.start_date, v_now), end_date = COALESCE(v_campaign.end_date, v_now + (v_campaign.weeks * 7) * interval '1 day'), paystack_verify_job = NULL, updated_at = now() WHERE id = v_campaign.id; RETURN jsonb_build_object('status','ok','payment_id',v_payment.id,'campaign_id',v_campaign.id,'amount_ngn',v_payment.amount_ngn,'paystack_reference',p_reference,'server_verified',true,'message','Campaign activated'); END IF; END IF; SELECT s.value INTO v_secret FROM public.app_secrets s WHERE s.name = 'paystack_secret_key'; IF v_secret IS NULL OR length(v_secret) < 10 THEN UPDATE public.advertising_payments SET status = 'succeeded', verified_at = v_now, updated_at = now() WHERE id = v_payment.id; UPDATE public.advertising_campaigns SET status = 'active', paystack_reference = p_reference, payment_verified_at = v_now, start_date = COALESCE(v_campaign.start_date, v_now), end_date = COALESCE(v_campaign.end_date, v_now + (v_campaign.weeks * 7) * interval '1 day'), updated_at = now() WHERE id = v_campaign.id; RETURN jsonb_build_object('status','ok','payment_id',v_payment.id,'campaign_id',v_campaign.id,'amount_ngn',v_payment.amount_ngn,'paystack_reference',p_reference,'server_verified',false,'message','Campaign activated (client callback verification)'); END IF; v_job := net.http_get('https://api.paystack.co/transaction/verify/' || p_reference, '{}'::jsonb, jsonb_build_object('Authorization', 'Bearer ' || v_secret), 10000); UPDATE public.advertising_payments SET paystack_verify_job = v_job, updated_at = now() WHERE id = v_payment.id; UPDATE public.advertising_campaigns SET paystack_verify_job = v_job, updated_at = now() WHERE id = v_campaign.id; RETURN jsonb_build_object('status','verifying','payment_id',v_payment.id,'message','Paystack verification started. Retrying to confirm...'); END; $function$;

-- 14. record_ad_impression: upsert daily impression (live analytics)
CREATE OR REPLACE FUNCTION public.record_ad_impression(p_campaign_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_campaign record; v_impressions int; v_clicks int; BEGIN SELECT * INTO v_campaign FROM public.advertising_campaigns WHERE id = p_campaign_id; IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Campaign not found.'); END IF; IF v_campaign.status <> 'active' THEN RETURN jsonb_build_object('error', 'Campaign is not active.'); END IF; IF v_campaign.end_date IS NOT NULL AND v_campaign.end_date < now() THEN RETURN jsonb_build_object('error', 'Campaign has ended.'); END IF; INSERT INTO public.advertising_impressions (campaign_id, impression_count, date, created_at) VALUES (p_campaign_id, 1, current_date, now()) ON CONFLICT (campaign_id, date) DO UPDATE SET impression_count = public.advertising_impressions.impression_count + 1; UPDATE public.advertising_campaigns SET total_impressions = COALESCE(total_impressions,0) + 1, updated_at = now() WHERE id = p_campaign_id; UPDATE public.advertisers SET total_impressions = COALESCE(total_impressions,0) + 1, updated_at = now() WHERE id = v_campaign.advertiser_id; SELECT COALESCE((SELECT sum(impression_count) FROM public.advertising_impressions WHERE campaign_id = p_campaign_id),0), COALESCE((SELECT sum(click_count) FROM public.advertising_clicks WHERE campaign_id = p_campaign_id),0) INTO v_impressions, v_clicks; RETURN jsonb_build_object('status','ok','campaign_id',p_campaign_id,'impressions',v_impressions,'clicks',v_clicks); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 15. record_ad_click: upsert daily click, return campaign contact info
CREATE OR REPLACE FUNCTION public.record_ad_click(p_campaign_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_campaign record; v_clicks int; v_impressions int; BEGIN SELECT * INTO v_campaign FROM public.advertising_campaigns WHERE id = p_campaign_id; IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Campaign not found.'); END IF; IF v_campaign.status <> 'active' THEN RETURN jsonb_build_object('error', 'Campaign is not active.'); END IF; IF v_campaign.end_date IS NOT NULL AND v_campaign.end_date < now() THEN RETURN jsonb_build_object('error', 'Campaign has ended.'); END IF; INSERT INTO public.advertising_clicks (campaign_id, click_count, date, created_at) VALUES (p_campaign_id, 1, current_date, now()) ON CONFLICT (campaign_id, date) DO UPDATE SET click_count = public.advertising_clicks.click_count + 1; UPDATE public.advertising_campaigns SET total_clicks = COALESCE(total_clicks,0) + 1, updated_at = now() WHERE id = p_campaign_id; UPDATE public.advertisers SET total_clicks = COALESCE(total_clicks,0) + 1, updated_at = now() WHERE id = v_campaign.advertiser_id; SELECT COALESCE((SELECT sum(click_count) FROM public.advertising_clicks WHERE campaign_id = p_campaign_id),0), COALESCE((SELECT sum(impression_count) FROM public.advertising_impressions WHERE campaign_id = p_campaign_id),0) INTO v_clicks, v_impressions; RETURN jsonb_build_object('status','ok','campaign_id',p_campaign_id,'clicks',v_clicks,'impressions',v_impressions,'contact_link',v_campaign.contact_link,'banner_url',v_campaign.banner_url,'copy_text',v_campaign.copy_text,'advertiser_id',v_campaign.advertiser_id); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 16. fetch_advertising_analytics: per-campaign impressions/clicks/ctr
CREATE OR REPLACE FUNCTION public.fetch_advertising_analytics(p_advertiser_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_profile_id uuid; v_rows jsonb; v_total_impressions int; v_total_clicks int; v_total_enquiries int; BEGIN IF p_advertiser_id IS NOT NULL THEN SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1; IF v_profile_id IS NULL THEN RETURN jsonb_build_object('error', 'Profile not found for this account.'); END IF; IF p_advertiser_id IS DISTINCT FROM (SELECT id FROM public.advertisers WHERE profile_id = v_profile_id LIMIT 1) AND NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Access denied.'); END IF; END IF; SELECT jsonb_agg(jsonb_build_object('id', c.id, 'campaign_name', c.campaign_name, 'category', c.category, 'status', c.status, 'weeks', c.weeks, 'placement_count', c.placement_count, 'total_amount_ngn', c.total_amount_ngn, 'impressions', COALESCE(im.impressions,0), 'clicks', COALESCE(cl.clicks,0), 'ctr', CASE WHEN COALESCE(im.impressions,0) > 0 THEN round((COALESCE(cl.clicks,0)::numeric / im.impressions) * 100, 2) ELSE 0 END, 'enquiries', (SELECT count(*) FROM public.advertising_enquiries e WHERE e.campaign_id = c.id), 'start_date', c.start_date, 'end_date', c.end_date) ORDER BY c.created_at DESC) INTO v_rows FROM public.advertising_campaigns c LEFT JOIN (SELECT campaign_id, sum(impression_count) AS impressions FROM public.advertising_impressions GROUP BY campaign_id) im ON im.campaign_id = c.id LEFT JOIN (SELECT campaign_id, sum(click_count) AS clicks FROM public.advertising_clicks GROUP BY campaign_id) cl ON cl.campaign_id = c.id WHERE (p_advertiser_id IS NULL OR c.advertiser_id = p_advertiser_id); SELECT COALESCE((SELECT sum(impression_count) FROM public.advertising_impressions i WHERE (p_advertiser_id IS NULL OR i.campaign_id IN (SELECT id FROM public.advertising_campaigns WHERE advertiser_id = p_advertiser_id))),0), COALESCE((SELECT sum(click_count) FROM public.advertising_clicks c WHERE (p_advertiser_id IS NULL OR c.campaign_id IN (SELECT id FROM public.advertising_campaigns WHERE advertiser_id = p_advertiser_id))),0), (SELECT count(*) FROM public.advertising_enquiries e WHERE e.advertiser_id = COALESCE(p_advertiser_id, (SELECT id FROM public.advertisers WHERE profile_id = v_profile_id LIMIT 1))) INTO v_total_impressions, v_total_clicks, v_total_enquiries; RETURN jsonb_build_object('campaigns', coalesce(v_rows,'[]'::jsonb), 'totals', jsonb_build_object('impressions', v_total_impressions, 'clicks', v_total_clicks, 'ctr', CASE WHEN v_total_impressions > 0 THEN round((v_total_clicks::numeric / v_total_impressions) * 100, 2) ELSE 0 END, 'enquiries', v_total_enquiries)); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 17. submit_advertising_enquiry: student enquiry/purchase from an ad
CREATE OR REPLACE FUNCTION public.submit_advertising_enquiry(p_campaign_id uuid, p_message text DEFAULT ''::text, p_contact_mode text DEFAULT 'enquiry') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_profile_id uuid; v_campaign record; v_enquiry_id uuid; BEGIN SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1; IF v_profile_id IS NULL THEN RETURN jsonb_build_object('error', 'Profile not found for this account.'); END IF; SELECT * INTO v_campaign FROM public.advertising_campaigns WHERE id = p_campaign_id; IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Campaign not found.'); END IF; IF v_campaign.status <> 'active' THEN RETURN jsonb_build_object('error', 'This campaign is not active.'); END IF; IF p_contact_mode NOT IN ('enquiry','purchase') THEN RETURN jsonb_build_object('error', 'Invalid contact mode.'); END IF; INSERT INTO public.advertising_enquiries (campaign_id, advertiser_id, student_profile_id, message, contact_mode, status, created_at, updated_at) VALUES (p_campaign_id, v_campaign.advertiser_id, v_profile_id, p_message, p_contact_mode, 'new', now(), now()) RETURNING id INTO v_enquiry_id; UPDATE public.advertisers SET enquiry_count = COALESCE(enquiry_count,0) + 1, updated_at = now() WHERE id = v_campaign.advertiser_id; RETURN jsonb_build_object('status','ok','enquiry_id',v_enquiry_id,'message','Enquiry sent to advertiser'); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 18. fetch_advertising_enquiries: enquiries for a campaign (advertiser or admin)
CREATE OR REPLACE FUNCTION public.fetch_advertising_enquiries(p_campaign_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_profile_id uuid; v_advertiser_id uuid; BEGIN SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1; IF v_profile_id IS NULL THEN RETURN jsonb_build_object('error', 'Profile not found for this account.'); END IF; SELECT advertiser_id INTO v_advertiser_id FROM public.advertising_campaigns WHERE id = p_campaign_id; IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Campaign not found.'); END IF; IF v_advertiser_id IS DISTINCT FROM (SELECT id FROM public.advertisers WHERE profile_id = v_profile_id LIMIT 1) AND NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Access denied.'); END IF; RETURN (SELECT jsonb_agg(jsonb_build_object('id', e.id, 'campaign_id', e.campaign_id, 'student_profile_id', e.student_profile_id, 'display_name', p.display_name, 'message', e.message, 'contact_mode', e.contact_mode, 'status', e.status, 'created_at', e.created_at) ORDER BY e.created_at DESC) FROM public.advertising_enquiries e LEFT JOIN public.profiles p ON p.id = e.student_profile_id WHERE e.campaign_id = p_campaign_id); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 19. fetch_my_advertising_enquiries: advertiser's own enquiries across campaigns
CREATE OR REPLACE FUNCTION public.fetch_my_advertising_enquiries() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_profile_id uuid; v_advertiser_id uuid; BEGIN SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1; IF v_profile_id IS NULL THEN RETURN jsonb_build_object('error', 'Profile not found for this account.'); END IF; SELECT id INTO v_advertiser_id FROM public.advertisers WHERE profile_id = v_profile_id LIMIT 1; IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Set up your advertiser profile first.'); END IF; RETURN (SELECT jsonb_agg(jsonb_build_object('id', e.id, 'campaign_id', e.campaign_id, 'campaign_name', c.campaign_name, 'student_profile_id', e.student_profile_id, 'display_name', p.display_name, 'message', e.message, 'contact_mode', e.contact_mode, 'status', e.status, 'created_at', e.created_at) ORDER BY e.created_at DESC) FROM public.advertising_enquiries e JOIN public.advertising_campaigns c ON c.id = e.campaign_id LEFT JOIN public.profiles p ON p.id = e.student_profile_id WHERE e.advertiser_id = v_advertiser_id); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 20. manage_advertising_package: admin upsert packages
CREATE OR REPLACE FUNCTION public.manage_advertising_package(p_package_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_price_ngn int DEFAULT NULL::int, p_duration_days int DEFAULT 7, p_placements text[] DEFAULT NULL, p_banner_sizes text[] DEFAULT NULL, p_target_audiences text[] DEFAULT NULL, p_campaign_limits int DEFAULT 1, p_promotional_offers text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_package_id uuid; BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; IF p_name IS NULL OR trim(p_name) = '' THEN RETURN jsonb_build_object('error', 'Package name is required.'); END IF; IF p_price_ngn IS NULL OR p_price_ngn <= 0 THEN RETURN jsonb_build_object('error', 'Package price must be positive.'); END IF; IF p_package_id IS NOT NULL THEN v_package_id := p_package_id; ELSE v_package_id := gen_random_uuid(); END IF; INSERT INTO public.advertising_packages (id, name, price_ngn, duration_days, placements, banner_sizes, target_audiences, campaign_limits, promotional_offers, created_at, updated_at) VALUES (v_package_id, p_name, p_price_ngn, p_duration_days, p_placements, p_banner_sizes, p_target_audiences, p_campaign_limits, p_promotional_offers, now(), now()) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, price_ngn = EXCLUDED.price_ngn, duration_days = EXCLUDED.duration_days, placements = EXCLUDED.placements, banner_sizes = EXCLUDED.banner_sizes, target_audiences = EXCLUDED.target_audiences, campaign_limits = EXCLUDED.campaign_limits, promotional_offers = EXCLUDED.promotional_offers, updated_at = now(); RETURN jsonb_build_object('status','ok','package_id',v_package_id,'message','Package saved'); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 21. fetch_promotional_banners: public active banners
CREATE OR REPLACE FUNCTION public.fetch_promotional_banners() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ BEGIN RETURN (SELECT jsonb_agg(jsonb_build_object('id', b.id, 'title', b.title, 'image_url', b.image_url, 'link_url', b.link_url, 'placement', b.placement, 'sort_order', b.sort_order) ORDER BY b.sort_order ASC) FROM public.promotional_banners b WHERE b.is_active); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 22. manage_promotional_banner: admin CRUD
CREATE OR REPLACE FUNCTION public.manage_promotional_banner(p_banner_id uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text, p_image_url text DEFAULT NULL::text, p_link_url text DEFAULT NULL, p_placement text DEFAULT NULL::text, p_is_active boolean DEFAULT true, p_sort_order int DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_banner_id uuid; BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; IF p_image_url IS NULL OR trim(p_image_url) = '' THEN RETURN jsonb_build_object('error', 'Banner image URL is required.'); END IF; IF p_placement IS NULL OR trim(p_placement) = '' THEN RETURN jsonb_build_object('error', 'Banner placement is required.'); END IF; IF p_banner_id IS NOT NULL THEN v_banner_id := p_banner_id; ELSE v_banner_id := gen_random_uuid(); END IF; INSERT INTO public.promotional_banners (id, title, image_url, link_url, placement, is_active, sort_order, created_at, updated_at) VALUES (v_banner_id, p_title, p_image_url, p_link_url, p_placement, p_is_active, p_sort_order, now(), now()) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, image_url = EXCLUDED.image_url, link_url = EXCLUDED.link_url, placement = EXCLUDED.placement, is_active = EXCLUDED.is_active, sort_order = EXCLUDED.sort_order, updated_at = now(); RETURN jsonb_build_object('status','ok','banner_id',v_banner_id,'message','Banner saved'); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;
